3	import { CORE_PURPOSE, runQuestionnaire } from './index.js';
4	
5	const createPrompt = (responses) => {
6	  const queue = [...responses];
7	  return async () => {
8	    if (!queue.length) {
9	      throw new Error('No more responses provided');
10	    }
11	    return queue.shift();
12	  };
13	};
14	
15	describe('runQuestionnaire', () => {
16	  it('uses user-facing flow with sensitive data', async () => {
17	    const prompt = createPrompt([
18	      { purpose: CORE_PURPOSE.USER_FACING, modelType: 'nlp', dataType: 'personal-consent' },
19	      { userImpact: 'high' },
20	      { dataProtection: 'full-protection' },
21	      { primaryMetric: 'accuracy' },
22	      { monitoring: 'automated-realtime' },
23	      { biasConsiderations: 'comprehensive' }
24	    ]);
25	
26	    const answers = await runQuestionnaire({ prompt });
27	
28	    expect(answers.core.purpose).toBe(CORE_PURPOSE.USER_FACING);
29	    expect(answers.impact).toEqual({ userImpact: 'high' });
30	    expect(answers.data).toEqual({ dataProtection: 'full-protection' });
31	    expect(answers.performance).toEqual({ primaryMetric: 'accuracy' });
32	    expect(answers.monitoring).toEqual({ monitoring: 'automated-realtime' });
33	    expect(answers.bias).toEqual({ biasConsiderations: 'comprehensive' });
34	  });
35	
36	  it('uses automation flow with non-personal data', async () => {
37	    const prompt = createPrompt([
38	      { purpose: CORE_PURPOSE.AUTOMATION, modelType: 'classification', dataType: 'public' },
39	      { automationImpact: 'autonomous' },
40	      { dataSource: 'internal' },
41	      { primaryMetric: 'f1' },
42	      { monitoring: 'user-feedback' },
43	      { biasConsiderations: 'planning' }
44	    ]);
45	
46	    const answers = await runQuestionnaire({ prompt });
47	
48	    expect(answers.impact).toEqual({ automationImpact: 'autonomous' });
49	    expect(answers.data).toEqual({ dataSource: 'internal' });
50	  });
51	
52	  it('defaults to general impact when purpose is other', async () => {
53	    const prompt = createPrompt([
54	      { purpose: 'other', modelType: 'regression', dataType: 'no-personal' },
55	      { generalImpact: 'medium' },
56	      { dataSource: 'mixed' },
57	      { primaryMetric: 'other' },
58	      { monitoring: 'manual-periodic' },
59	      { biasConsiderations: 'not-applicable' }
60	    ]);
61	
62	    const answers = await runQuestionnaire({ prompt });
63	
64	    expect(answers.impact).toEqual({ generalImpact: 'medium' });
65	  });
66	
67	  it('throws when prompt is missing', async () => {
68	    await expect(runQuestionnaire({})).rejects.toThrow(TypeError);
69	  });
70	});
